package com.jobpilot.integration;import com.jobpilot.job.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;
@Service public class JobImportService{private final SearchPreferenceRepository prefs;private final JobOfferRepository jobs;private final AdzunaClient client;private final MailAlertService mail;public JobImportService(SearchPreferenceRepository p,JobOfferRepository j,AdzunaClient c,MailAlertService m){prefs=p;jobs=j;client=c;mail=m;}@Transactional public int sync(SearchPreference p){int added=0;for(var r:client.search(p)){if(jobs.existsByUserIdAndExternalId(p.getUser().getId(),r.id()))continue;var j=new JobOffer();j.setUser(p.getUser());j.setExternalId(r.id());j.setTitle(r.title());j.setCompany(r.company()==null?"Unknown":r.company().display_name());j.setLocation(r.location()==null?null:r.location().display_name());String description=r.description()==null?"":r.description();j.setRemote((j.getLocation()!=null&&j.getLocation().toLowerCase().contains("remote"))||description.toLowerCase().contains("remote"));j.setDescription(description);j.setUrl(r.redirect_url());j.setSalaryMin(r.salary_min());j.setSalaryMax(r.salary_max());j.setSource("ADZUNA");j.setPublishedAt(r.created()==null?null:r.created().toLocalDateTime());jobs.save(j);added++;}p.setLastSyncAt(LocalDateTime.now());prefs.save(p);if(added>0)mail.newJobs(p.getUser(),added);return added;}@Scheduled(cron="0 0 7 * * *")public void dailySync(){prefs.findAll().forEach(this::sync);}}
